import{_ as e,c as r,o as h,af as i}from"./chunks/framework.BKeRpnBD.js";const b=JSON.parse('{"title":"小畜","description":"周易集解 - 小畜","frontmatter":{"title":"小畜","description":"周易集解 - 小畜"},"headers":[],"relativePath":"classics/jijie/009.md","filePath":"classics/jijie/009.md"}'),l={name:"classics/jijie/009.md"};function n(d,a,p,t,s,c){return h(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="小畜" tabindex="-1">小畜 <a class="header-anchor" href="#小畜" aria-label="Permalink to “小畜”">​</a></h1><h2 id="小畜-1" tabindex="-1">小畜 <a class="header-anchor" href="#小畜-1" aria-label="Permalink to “小畜”">​</a></h2><h2 id="卦辭" tabindex="-1">卦辭 <a class="header-anchor" href="#卦辭" aria-label="Permalink to “卦辭”">​</a></h2><p>小畜，亨。密雲不雨，自我西郊。</p><h2 id="卦辭注" tabindex="-1">卦辭注 <a class="header-anchor" href="#卦辭注" aria-label="Permalink to “卦辭注”">​</a></h2><p>《序卦》曰：比必有所畜，故受之以小畜。</p><p>崔憬曰：下順從而上下應之，則有所畜矣。</p><p>韓康伯曰：由比而畜，故曰小畜也。</p><p>侯果曰：四為畜主，體又稱小，唯九三被畜，下剛皆通，是以小畜亨也。</p><p>崔憬曰：雲如不雨，積我西邑之郊，施澤未通，以明小畜之義。</p><p>案：雲雨者，陰之氣也。今小畜五陽而一陰，既微少，才作密雲，故未能為雨。四互居兌，西郊之象也。</p><h2 id="彖" tabindex="-1">彖 <a class="header-anchor" href="#彖" aria-label="Permalink to “彖”">​</a></h2><p>《彖》曰：小畜，柔得位而上下應之，曰小畜。健而巽，剛中而志行，乃亨。密雲不雨，尚往也。自我西郊，施未行也。</p><h2 id="彖傳注" tabindex="-1">彖傳注 <a class="header-anchor" href="#彖傳注" aria-label="Permalink to “彖傳注”">​</a></h2><p>王弼曰：謂六四也。成卦之義，在此一爻者也。體無二陰以分其應，既得其位，而上下應之，三不能陵，小畜之義。</p><p>虞翻曰：需上變為巽，與豫旁通。豫四之坤初為復，復小陽潛，所畜者少，故曰小畜。二失位，五剛中正，二變應之，故志行乃亨也。</p><p>虞翻曰：密，小也。兌為密。需坎昇天為雲，墜地稱雨。上變為陽，坎象半見。故「密雲不雨，上往也」。</p><p>虞翻曰：豫坤為自我。兌為西，乾為郊，雨生於西，故自我西郊。九二未變，故施未行矣。</p><p>荀爽曰：體兌位秋，故曰西郊也。時當收斂，臣不專賞，故施未行。喻文王也。</p><h2 id="象" tabindex="-1">象 <a class="header-anchor" href="#象" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：風行天上，小畜。君子以懿文德。</p><h2 id="象傳注" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注" aria-label="Permalink to “象傳注”">​</a></h2><p>《九家易》曰：風者天之命令也，今行天上，則是令未下行，畜而未下，小畜之義也。</p><p>虞翻曰：君子，謂乾。懿，美也。豫坤為文。乾為德，離為明。初至四體夬，為書契。乾離照坤，故懿文德也。</p><h2 id="初九" tabindex="-1">初九 <a class="header-anchor" href="#初九" aria-label="Permalink to “初九”">​</a></h2><p>初九，復自道，何其咎，吉。</p><h2 id="象-1" tabindex="-1">象 <a class="header-anchor" href="#象-1" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：復自道，其義吉也。</p><h2 id="象傳注-1" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注-1" aria-label="Permalink to “象傳注”">​</a></h2><p>虞翻曰：謂從豫四之初成復卦，故復自道。出入無疾，朋來無咎，何其咎，吉。乾稱道也。</p><h2 id="九二" tabindex="-1">九二 <a class="header-anchor" href="#九二" aria-label="Permalink to “九二”">​</a></h2><p>九二，牽復，吉。</p><h2 id="九二注" tabindex="-1">九二注 <a class="header-anchor" href="#九二注" aria-label="Permalink to “九二注”">​</a></h2><p>崔憬曰：四柔得位，群剛所應，二以中和牽復自守，不失於行也。</p><h2 id="象-2" tabindex="-1">象 <a class="header-anchor" href="#象-2" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：牽覆在中，亦不自失也。</p><h2 id="象傳注-2" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注-2" aria-label="Permalink to “象傳注”">​</a></h2><p>虞翻曰：變應五，故不自失，與比二同義也。</p><h2 id="九三" tabindex="-1">九三 <a class="header-anchor" href="#九三" aria-label="Permalink to “九三”">​</a></h2><p>九三，輿說輻，夫妻反目。</p><h2 id="九三注" tabindex="-1">九三注 <a class="header-anchor" href="#九三注" aria-label="Permalink to “九三注”">​</a></h2><p>虞翻曰：豫坤為車，為輻。至三成乾，坤象不見，故車說輻。馬君及俗儒皆以乾為車，非也。</p><p>虞翻曰：逸震為夫，為反。巽為妻。離為目。今夫妻共在四，離火動上，目象不正，巽多白眼，夫妻反目。妻當在內，夫當在外，今妻乘夫而出在外，象曰不能正室。三體離需，飲食之道。飲食有訟，故爭而反目也。</p><h2 id="象-3" tabindex="-1">象 <a class="header-anchor" href="#象-3" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：夫妻反目，不能正室也。</p><h2 id="象傳注-3" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注-3" aria-label="Permalink to “象傳注”">​</a></h2><p>《九家易》曰：四互體離，離為目也。離既不正，五引而上，三引而下，故反目也。輿以輪成車，夫以妻成室。今以妻乘夫，其道逆，故不能正室。</p><h2 id="六四" tabindex="-1">六四 <a class="header-anchor" href="#六四" aria-label="Permalink to “六四”">​</a></h2><p>六四，有孚，血去惕出，無咎。</p><h2 id="六四注" tabindex="-1">六四注 <a class="header-anchor" href="#六四注" aria-label="Permalink to “六四注”">​</a></h2><p>虞翻曰：孚謂五。逸坎為血，為惕。惕，憂也。震為出，變成小畜，坎象不見，故血去惕出。得位承五，故無咎也。</p><h2 id="象-4" tabindex="-1">象 <a class="header-anchor" href="#象-4" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：有孚惕出，上合志也。</p><h2 id="象傳注-4" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注-4" aria-label="Permalink to “象傳注”">​</a></h2><p>荀爽曰：血以喻陰。四陰，臣象。有信順五。惕，疾也。四當去初，疾出從五，故曰上合志也。</p><h2 id="九五" tabindex="-1">九五 <a class="header-anchor" href="#九五" aria-label="Permalink to “九五”">​</a></h2><p>九五，有孚攣如，富以其鄰。</p><h2 id="九五注" tabindex="-1">九五注 <a class="header-anchor" href="#九五注" aria-label="Permalink to “九五注”">​</a></h2><p>虞翻曰：孚五，謂二也。攣，引也。巽為繩，逸艮為手。二失位，五欲其變，故曰攣如。以，及也。五貴，稱富。鄰，謂三。兌西震東，稱鄰。二變承三，故富以其鄰，《象》曰「不獨富」。二變為既濟，與東西鄰同義。</p><h2 id="象-5" tabindex="-1">象 <a class="header-anchor" href="#象-5" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：有孚攣如，不獨富也。</p><h2 id="象傳注-5" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注-5" aria-label="Permalink to “象傳注”">​</a></h2><p>《九家易》曰：有信，下三爻也。體巽，故攣如，如謂連接其鄰。鄰謂四也。五以四陰作財，與下三陽共之，故曰不獨富也。</p><h2 id="上九" tabindex="-1">上九 <a class="header-anchor" href="#上九" aria-label="Permalink to “上九”">​</a></h2><p>上九，既雨既處，尚得載，婦貞厲。月幾望，君子徵兇。</p><h2 id="上九注" tabindex="-1">上九注 <a class="header-anchor" href="#上九注" aria-label="Permalink to “上九注”">​</a></h2><p>虞翻曰：既，已也。應在三。坎水零為雨。巽為處，謂二已變，三體坎雨，故既雨既處。坎雲復天，坎為車，載積在坎上，故上得積載。巽為婦，坎成巽壞，故婦貞厲。</p><p>虞翻曰：幾，近也。坎月離日，上已正，需時成坎，與離相望。兌西震東，日月象對，故月幾望。上變陽消，之坎為疑，故君子徵有所疑矣。與歸妹、中孚月幾望義同也。</p><h2 id="象-6" tabindex="-1">象 <a class="header-anchor" href="#象-6" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：既雨既處，德積載也。君子徵兇，有所疑也。</p><h2 id="象傳注-6" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注-6" aria-label="Permalink to “象傳注”">​</a></h2><p>虞翻曰：巽消承坎，故德積載。坎習為積也。</p><p>虞翻曰：變坎為盜，故有所疑也。</p>',73)])])}const f=e(l,[["render",n]]);export{b as __pageData,f as default};
